using System;using System.IO;using System.Linq;using System.Collections.Generic;using Cysharp.Threading.Tasks;using UnityEditor;using UnityEngine;using SushiAndFish.Casino;using SushiAndFish.Casino.Original;using SushiAndFish.Casino.Original.CasinoLab;
public static partial class CityExpansionPlayAudit {
 [Serializable]public class PoseTrace{public string path;public Vector3 world,local,scale,lossy;}
 [Serializable]public class ColliderTrace{public string path,mesh;public Vector3 min,max,localMeshMin,localMeshMax;public bool enabled,active,renderer;}
 [Serializable]public class FloorTrace{public string utc;public List<PoseTrace> parents=new List<PoseTrace>();public List<ColliderTrace> colliders=new List<ColliderTrace>();public List<string> rays=new List<string>();}
 public static void DiagnosticFloorTwo(){SessionState.SetBool(Key+"floor2diag",true);ScreensAndCoast();}
 static async UniTask DumpFloorTwo(ParkCasinoIntegration c){await CompletionFloor(c,2);var data=new FloorTrace{utc=DateTime.UtcNow.ToString("o")};var pad=c.ModuleRoot.GetComponentsInChildren<Keypad>(false).First(p=>p.NetworkcasinoGame is CrossyRoad);var point=pad.transform.position;for(var t=pad.transform;t;t=t.parent)data.parents.Add(new PoseTrace{path=FullPath(t),world=t.position,local=t.localPosition,scale=t.localScale,lossy=t.lossyScale});foreach(var co in c.ModuleRoot.GetComponentsInChildren<Collider>(true).Where(x=>Mathf.Abs(x.bounds.center.x-point.x)<18&&Mathf.Abs(x.bounds.center.z-point.z)<18)){var m=(co as MeshCollider)?.sharedMesh;data.colliders.Add(new ColliderTrace{path=FullPath(co.transform),enabled=co.enabled,active=co.gameObject.activeInHierarchy,renderer=co.GetComponent<Renderer>()&&co.GetComponent<Renderer>().enabled,min=co.bounds.min,max=co.bounds.max,mesh=m?AssetDatabase.GetAssetPath(m):"",localMeshMin=m?m.bounds.min:Vector3.zero,localMeshMax=m?m.bounds.max:Vector3.zero});}foreach(float dist in new[]{0f,1.3f,1.8f,2.3f,3.3f}){var p=point+pad.transform.forward*dist;data.rays.Add("RAY "+p);foreach(var h in Physics.RaycastAll(new Vector3(p.x,point.y+2,p.z),Vector3.down,20,~0,QueryTriggerInteraction.Ignore).OrderBy(h=>h.distance))data.rays.Add(h.point+" normal="+h.normal+" "+FullPath(h.transform));}File.WriteAllText(Path.Combine(Reports,"screenshot-floor2-pose-diagnostic.json"),JsonUtility.ToJson(data,true));completion.passed=false;CompleteStage("DIAGNOSED_FLOOR2");}
}
